+  await g.page.evaluate(() => window.WishweaveGame.resume());
+  await frames(0.4);
+  r = await ribbon();
+  check(r.time === hold0.time && r.loop.f === hold0.loop.f, 'still frozen after resume (clock and Loop)');
+
