+  r = await ribbon();
+  check(r.time === hold0.time, 'the whole lesson took no race time (' + t0.toFixed(3) + ')');
+  check(r.loop.f === hold0.loop.f, 'Loop resumes from his real, held position (f ' + r.loop.f.toFixed(4) + ')');
